async function resolveAgentIdentity(config) {
  const agent = config.agent ?? "nexus";
  let command;
  let argsPrefix = [];
  if (agent === "nexus") {
    if (config.qualification === true && (typeof config.nexusExecutable !== "string" || !path.isAbsolute(config.nexusExecutable))) {
      return { record: null, problem: "qualification requires nexusExecutable to be the absolute path of the installed RC" };
    }
    if (config.qualification === true && (typeof config.expectedAgentVersion !== "string" || !config.expectedAgentVersion.trim())) {
      return { record: null, problem: "qualification requires expectedAgentVersion to pin the installed RC" };
    }
    if (config.qualification === true && !/^[0-9a-f]{64}$/.test(config.nexusPackageSha256 ?? "")) {
      return { record: null, problem: "qualification requires nexusPackageSha256 from the installed RC release asset" };
    }
    if (config.nexusExecutable !== undefined) {
      if (typeof config.nexusExecutable !== "string" || !path.isAbsolute(config.nexusExecutable)) {
        return { record: null, problem: "nexusExecutable must be an absolute installed Nexus executable path" };
      }
      command = path.resolve(config.nexusExecutable);
      try {
        if (fs.realpathSync(command) === fs.realpathSync(path.join(ROOT, "cli/dist/index.js"))) {
          return { record: null, problem: "runner API must use the installed Nexus executable, not the checkout cli/dist/index.js" };
        }
      } catch {}
    } else {
      command = process.execPath;
      argsPrefix = [path.join(ROOT, "cli/dist/index.js")];
    }
  } else if (["goose", "opencode", "aider"].includes(agent)) {
    command = resolvePathExecutable(agent, { ...process.env, ...(config.env ?? {}) }) ?? agent;
  } else {
    return { record: null, problem: `eval agent '${agent}' has no versioned adapter` };
  }

  const required = config.qualification === true || config.expectedAgentVersion !== undefined;
  let candidatePath;
  try { candidatePath = fs.realpathSync(command); }
  catch (error) { return { record: null, problem: required ? `could not identify ${agent} executable (${error.message})` : null, command, argsPrefix }; }
  argsPrefix = argsPrefix.map((item) => path.isAbsolute(item) ? fs.realpathSync(item) : item);
  // Version probes execute candidate-controlled code and must share the enforced writable-storage cap.
  const probeWorkspace = fs.mkdtempSync(path.join(config.resources?.workspaceRoot ?? os.tmpdir(), "nexus-eval-version-workspace-"));
  let probe;
  try {
    if (config.runAs) grantRunAsAccess(config.runAs, [probeWorkspace]);
    const runtimePaths = [candidatePath, ...argsPrefix.filter((item) => path.isAbsolute(item)).map((item) => fs.realpathSync(item))];
    const isCheckoutNexus = agent === "nexus" && argsPrefix[0] === path.join(ROOT, "cli/dist/index.js");
    if (isCheckoutNexus) {
      runtimePaths.push(path.join(ROOT, "cli/dist"));
      const modules = path.join(ROOT, "cli/node_modules");
      if (fs.existsSync(modules)) {
        for (const entry of fs.readdirSync(modules, { withFileTypes: true })) {
          if (entry.isDirectory() && entry.name !== ".bin") runtimePaths.push(path.join(modules, entry.name));
        }
      }
      const coreBinary = path.join(ROOT, "core/target/release/harness-core");
      if (fs.existsSync(coreBinary)) runtimePaths.push(coreBinary);
    }
    const allowedRoots = [...new Set([...(config.sandboxRuntimeRoots ?? []), ...(isCheckoutNexus ? [ROOT] : [])])];
    const spec = isolatedProcessArgv({
      cwd: probeWorkspace,
      command: candidatePath,
      argv: [...argsPrefix, "--version"],
      readOnlyPaths: [...new Set(runtimePaths)],
      allowedRoots,
      allowedFiles: [candidatePath, ...argsPrefix.filter((item) => path.isAbsolute(item))],
      timeoutMs: 5000,
      protectedCorpusPaths: protectedCorpusPathsForRun(),
    });
    const wrapped = config.runAs ? asUserSpec(config.runAs, spec) : spec;
    probe = await runIsolatedProcess(wrapped, { outputLimit: 4096, resources: config.resources ?? null });
  } finally {
    fs.rmSync(probeWorkspace, { recursive: true, force: true });
  }
  const output = `${probe?.stdout ?? ""}${probe?.stderr ?? ""}`.trim();
  const version = output.split(/\r?\n/, 1)[0]?.trim().slice(0, 200) || null;
  if (probe?.containmentProblem || probe?.error || probe?.status !== 0 || probe?.timedOut || probe?.overflow || !version) {
    const detail = output ? `; output=${JSON.stringify(output.slice(0, 600))}` : "";
    const reason = probe?.containmentProblem ?? probe?.error ?? (probe?.timedOut ? "timeout" : probe?.overflow ? "output limit exceeded" : `exit ${probe?.status ?? "unknown"}${detail}`);
    return { record: null, problem: required ? `could not identify ${agent} version (${reason})` : null, command, argsPrefix };
  }

function resolvePathExecutable(command, env) {
  for (const directory of (env.PATH ?? "").split(path.delimiter).filter(Boolean)) {
    const candidate = path.resolve(directory, command);
    try {
      if (fs.statSync(candidate).isFile()) return fs.realpathSync(candidate);
    } catch {}
  }
  return null;
}

function sha256File(file) {
  return new Promise((resolve, reject) => {
    const hash = createHash("sha256");
    const stream = fs.createReadStream(file);
    stream.on("data", (chunk) => hash.update(chunk));
    stream.on("error", reject);
    stream.on("end", () => resolve(hash.digest("hex")));
  });
}

async function runAgent(task, ws, home, budget, agentIdentity, proxyDirectory, localToken, proxy) {
  if (task.t4RunnerFault !== "sigterm_resume") {
    return runAgentAttempt(task, ws, home, budget, agentIdentity, proxyDirectory, localToken);
  }
  if (task.tier !== "T4" || (config.agent ?? "nexus") !== "nexus" || config.qualification !== true || !config.resources) {
    throw new Error("sigterm_resume requires an installed Nexus qualification run with the kernel resource contract");
  }
  const interrupted = await runAgentAttempt(task, ws, home, budget, agentIdentity, proxyDirectory, localToken, { signalAfterAnswer: true, proxy });
  const signal = interrupted.t4Signal;
  if (!signal?.delivered) return { ...interrupted, t4FaultsInjected: [] };
  const resumed = await runAgentAttempt(task, ws, home, budget, agentIdentity, proxyDirectory, localToken, { resume: true });
  const evidence = {
    signal: "SIGTERM",
    delivered: signal.delivered,
    deliveredProcesses: signal.deliveredProcesses,
    forced: signal.forced,
    firstExitCode: signal.firstExitCode,
    payloadExitSignal: signal.payloadExitSignal,
    supervisorWrapperExitSignal: signal.supervisorWrapperExitSignal,
    signalDuringActiveTurn: signal.signalDuringActiveTurn,
    resumed: resumed.code === 0 && resumed.json?.turn?.execution === "COMPLETED",
    resumeExitCode: resumed.code,
    resumeTurnExecution: resumed.json?.turn?.execution ?? null,
  };
  return {
    ...resumed,
    stdout: `${interrupted.stdout}\n--- T4 SIGTERM interruption ---\n${resumed.stdout}`,
    stderr: `${interrupted.stderr}\n--- T4 resume attempt ---\n${resumed.stderr}`,
    t4FaultsInjected: [{ kind: "sigterm_resume", source: "task_fixture_or_runner", evidence }],
  };
}

