function runProcess(script, args, { cwd, captureStdout = false } = {}) {
  return new Promise((resolve, reject) => {
    const child = spawn(process.execPath, [script, ...args], {
      cwd,
      stdio: captureStdout ? ["ignore", "pipe", "ignore"] : "ignore",
      shell: false,
    });
