test("parseEvalRuns accepts only positive safe whole numbers", () => {
  assert.equal(parseEvalRuns(undefined), 1);
  assert.equal(parseEvalRuns("3"), 3);
  for (const value of ["0", "-1", "1.5", " 2", "2x", "9007199254740992"]) {
    assert.throws(() => parseEvalRuns(value), /positive whole number|integer range/);
  }
});

test("startup HOME isolation is limited to eval --isolated-home and restores the caller environment", () => {
  const originalHome = process.env.HOME;
  assert.equal(isolateEvalCommandHome(["run", "--isolated-home"]), undefined);
  const restore = isolateEvalCommandHome(["eval", "--isolated-home"]);
  assert.equal(typeof restore, "function");
  const isolatedHome = process.env.HOME;
  try {
    assert.ok(isolatedHome && isolatedHome !== originalHome);
    assert.equal(process.env.XDG_CONFIG_HOME, path.join(isolatedHome ?? "", ".config"));
  } finally {
    restore?.();
  }
  assert.equal(process.env.HOME, originalHome);
  assert.ok(isolatedHome && !fs.existsSync(isolatedHome));
});

test("runEvalCommand repeats evaluation and writes a structured score without free-form output", async () => {
  const root = fs.mkdtempSync(path.join(os.tmpdir(), "nexus-eval-cli-test-"));
  const output = path.join(root, "scores", "score.json");
  let runCount = 0;
  try {
    const result = await runEvalCommand(
      { dataset: "dataset.jsonl", runs: "2", output },
      () => ({ workspace: root } as HarnessConfig),
      runner(() => { runCount++; }),
    );

    assert.equal(runCount, 2);
    assert.equal(result.schemaVersion, 1);
    assert.equal(result.runs, 2);
    assert.deepEqual(result.scores.map((score) => score.run), [1, 2]);
    assert.equal(result.scores[0].results[0].tokensConsumed, 12);
    const written = fs.readFileSync(output, "utf8");
    assert.deepEqual(JSON.parse(written), result);
    assert.equal(written.includes("private patch text"), false);
    assert.equal(written.includes("private test output"), false);
  } finally {
    fs.rmSync(root, { recursive: true, force: true });
  }
});

test("isolated-home gives every run a separate private home and restores the caller environment", async () => {
  const root = fs.mkdtempSync(path.join(os.tmpdir(), "nexus-eval-home-test-"));
  const originalHome = process.env.HOME;
  const observedHomes: string[] = [];
  try {
    const result = await runEvalCommand(
      { dataset: "dataset.jsonl", runs: 2, isolatedHome: true },
      () => {
        observedHomes.push(process.env.HOME ?? "");
        assert.equal(process.env.XDG_CONFIG_HOME, path.join(process.env.HOME ?? "", ".config"));
        return { workspace: root } as HarnessConfig;
      },
      runner(() => { observedHomes.push(process.env.HOME ?? ""); }),
    );

    assert.equal(result.isolatedHome, true);
    assert.equal(new Set(observedHomes).size, 2);
    assert.ok(observedHomes.every((home) => home !== originalHome));
    assert.equal(process.env.HOME, originalHome);
    assert.ok(observedHomes.every((home) => !fs.existsSync(home)));
  } finally {
    if (originalHome === undefined) delete process.env.HOME;
    else process.env.HOME = originalHome;
    fs.rmSync(root, { recursive: true, force: true });
  }
});

test("installed versioned eval imports only package runtime and forwards scoring config without oracle fields", async () => {
  const root = fs.mkdtempSync(path.join(os.tmpdir(), "nexus-installed-eval-test-"));
  const output = path.join(root, "scores", "score.json");
  const calls: unknown[] = [];
  (globalThis as typeof globalThis & { __nexusEvalCapture?: unknown[] }).__nexusEvalCapture = calls;
  try {
    const packageRoot = path.join(root, "package");
    fs.mkdirSync(path.join(packageRoot, "bin"), { recursive: true });
    fs.mkdirSync(path.join(packageRoot, "eval"), { recursive: true });
    fs.writeFileSync(path.join(packageRoot, "bin", "nexus"), "#!/bin/sh\nexit 0\n", { mode: 0o700 });
    const runnerApiPath = path.join(packageRoot, "eval", "runner_api.mjs");
    fs.writeFileSync(runnerApiPath, [
      "export async function runVersionedEvaluation(options) {",
      "  globalThis.__nexusEvalCapture.push(options);",
      "  return { outputDir: options.outputDir, resultsFile: options.outputDir + '/results.jsonl', manifestFile: options.outputDir + '/manifest.json', scoreFile: options.outputDir + '/score.json', score: { passRate: 1 } };",
      "}",
    ].join("\n"));
    const resolved = resolveInstalledEvalRuntime({ NEXUS_HOME: packageRoot });
    assert.equal(resolved.packageRoot, fs.realpathSync(packageRoot));
    assert.equal(resolved.nexusExecutable, fs.realpathSync(path.join(packageRoot, "bin", "nexus")));

    const result = await runVersionedEvalCommand({
      dataset: path.join(root, "user-dataset"),
      output,
      runs: "2",
      split: "benchmark",
      maxSteps: 17,
      maxMinutes: 31,
    }, {
      endpoint: "http://127.0.0.1:8080/v1",
      model: "installed-test-model",
      apiKey: "synthetic-installed-eval-key",
      maxSteps: 30,
      temperature: 0.1,
      contextLimit: 4096,
      completionReserveTokens: 512,
      workspace: root,
    } as HarnessConfig, () => resolved);

    const call = calls[0] as { config: Record<string, unknown>; nexusExecutable: string; dataset: string; outputDir: string; runs: number; split: string };
    assert.equal(call.nexusExecutable, resolved.nexusExecutable);
    assert.equal(call.dataset, path.join(root, "user-dataset"));
    assert.equal(call.runs, 2);
    assert.equal(call.split, "benchmark");
    assert.deepEqual(call.config.sandboxRuntimeRoots, [resolved.packageRoot]);
    assert.deepEqual(call.config.sampling, { temperature: 0.1 });
    assert.equal(call.config.endpoint, "http://127.0.0.1:8080/v1");
    assert.equal(call.config.model, "installed-test-model");
    assert.equal(call.config.apiKey, "synthetic-installed-eval-key");
    assert.equal(Object.hasOwn(call.config, "hidden"), false);
    assert.equal(Object.hasOwn(call.config, "oracles"), false);
    assert.deepEqual(JSON.parse(fs.readFileSync(output, "utf8")).score, { passRate: 1 });
    assert.equal(fs.statSync(output).mode & 0o777, 0o600);
  } finally {
    delete (globalThis as typeof globalThis & { __nexusEvalCapture?: unknown[] }).__nexusEvalCapture;
    fs.rmSync(root, { recursive: true, force: true });
  }
});
