test("installed versioned eval imports only package runtime and forwards scoring config without oracle fields", async () => {
  const root = fs.mkdtempSync(path.join(os.tmpdir(), "nexus-installed-eval-test-"));
  const output = path.join(root, "scores", "score.json");
  const calls: unknown[] = [];
  (globalThis as typeof globalThis & { __nexusEvalCapture?: unknown[] }).__nexusEvalCapture = calls;
  try {
    const packageRoot = path.join(root, "package");
    fs.mkdirSync(path.join(packageRoot, "bin"), { recursive: true });
    fs.mkdirSync(path.join(packageRoot, "eval"), { recursive: true });
    fs.writeFileSync(path.join(packageRoot, "bin", "nexus"), "#!/bin/sh\nexit 0\n", { mode: 0o700 });
    const runnerApiPath = path.join(packageRoot, "eval", "runner_api.mjs");
    fs.writeFileSync(runnerApiPath, [
      "export async function runVersionedEvaluation(options) {",
      "  globalThis.__nexusEvalCapture.push(options);",
      "  return { outputDir: options.outputDir, resultsFile: options.outputDir + '/results.jsonl', manifestFile: options.outputDir + '/manifest.json', scoreFile: options.outputDir + '/score.json', score: { passRate: 1 } };",
      "}",
    ].join("\n"));
    const resolved = resolveInstalledEvalRuntime({ NEXUS_HOME: packageRoot });
    assert.equal(resolved.packageRoot, fs.realpathSync(packageRoot));
    assert.equal(resolved.nexusExecutable, fs.realpathSync(path.join(packageRoot, "bin", "nexus")));

    const result = await runVersionedEvalCommand({
      dataset: path.join(root, "user-dataset"),
      output,
      runs: "2",
      split: "benchmark",
      maxSteps: 17,
      maxMinutes: 31,
    }, {
      endpoint: "http://127.0.0.1:8080/v1",
      model: "installed-test-model",
      apiKey: "synthetic-installed-eval-key",
      maxSteps: 30,
      temperature: 0.1,
      contextLimit: 4096,
      completionReserveTokens: 512,
      workspace: root,
    } as HarnessConfig, () => resolved);

    const call = calls[0] as { config: Record<string, unknown>; nexusExecutable: string; dataset: string; outputDir: string; runs: number; split: string };
    assert.equal(call.nexusExecutable, resolved.nexusExecutable);
    assert.equal(call.dataset, path.join(root, "user-dataset"));
    assert.equal(call.runs, 2);
    assert.equal(call.split, "benchmark");
    assert.deepEqual(call.config.sandboxRuntimeRoots, [resolved.packageRoot]);
    assert.deepEqual(call.config.sampling, { temperature: 0.1 });
    assert.equal(call.config.endpoint, "http://127.0.0.1:8080/v1");
    assert.equal(call.config.model, "installed-test-model");
    assert.equal(call.config.apiKey, "synthetic-installed-eval-key");
    assert.equal(Object.hasOwn(call.config, "hidden"), false);
    assert.equal(Object.hasOwn(call.config, "oracles"), false);
    assert.deepEqual(JSON.parse(fs.readFileSync(output, "utf8")).score, { passRate: 1 });
    assert.equal(fs.statSync(output).mode & 0o777, 0o600);
  } finally {
    delete (globalThis as typeof globalThis & { __nexusEvalCapture?: unknown[] }).__nexusEvalCapture;
    fs.rmSync(root, { recursive: true, force: true });
  }
});
